contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: token must be underlyingCollateralToken address, amount and recipient
    function run(address token, uint256 amount, address to) public payable {
        // ensure we only test collateral deposit path
        require(amount > 0);

        // read before balance (via public view on SizeView.getUserView -> collateralTokenBalance)
        // getUserView is external view and returns a struct; call it for 'to'
        ISizeView.UserView memory before = c.getUserView(to);
        uint256 beforeBalance = before.collateralTokenBalance;

        // try deposit; capture revert
        bool reverted = false;
        // call must be top-level; use try/catch to detect revert
        try c.deposit{value: msg.value}(DepositParams({token: token, amount: amount, to: to})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        ISizeView.UserView memory after = c.getUserView(to);
        uint256 afterBalance = after.collateralTokenBalance;

        // If deposit reverted then balance must be unchanged; otherwise balance must be >= before + amount
        assert(reverted ? afterBalance == beforeBalance : afterBalance >= beforeBalance + amount);
    }

    // Required to receive ETH in case caller funds this test to forward msg.value to c.deposit
    receive() external payable {}
}

