contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call deposit to mint collateral tokens. Parameters:
    // token - address to deposit (use underlyingCollateralToken from c.oracle/data via public view)
    // amount - amount to deposit
    // to - recipient address to credit (use this contract address to observe balances)
    function run(address token, uint256 amount, address to) public payable {
        // require this contract has enough ETH if depositing WETH; otherwise we only allow ERC20-path tests
        require(amount > 0);

        // Read data view to obtain the underlying collateral token address exposed by c
        // c.data() returns DataView with underlyingCollateralToken field
        // Note: call as view to observe available collateral token address
        C.DataView memory dv = c.data();
        address underlyingCollateral = address(dv.underlyingCollateralToken);

        // We only proceed when the provided token matches the protocol's underlying collateral token
        // so that deposit will attempt collateral-token deposit path (not underlying borrow token)
        require(token == underlyingCollateral);

        // For safety: when depositing ETH/WETH path is not used, ensure msg.value=0
        // This run function is not payable for ETH path; but if msg.value were used, tests would need balance setup.
        require(msg.value == 0);

        // Before balance: read collateral token balance reported by the protocol for `to` via getUserView
        C.UserView memory beforeView = c.getUserView(to);
        uint256 beforeCollateral = beforeView.collateralTokenBalance;

        // Now perform the deposit call. We must ensure this contract has approved c to pull tokens.
        // As the test harness cannot mint or approve arbitrary ERC20s, we rely on the runtime to set token approvals
        // and balances appropriately for some inputs. We attempt the call and record whether it reverted.
        bool reverted;
        try c.deposit{value: 0}(C.DepositParams({token: token, amount: amount, to: to})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After view
        C.UserView memory afterView = c.getUserView(to);
        uint256 afterCollateral = afterView.collateralTokenBalance;

        // General rule (assert): If deposit did not revert then the protocol's collateralToken balance for `to` is >= before + min(amount, afterCollateral)
        // More usefully: if deposit succeeds, afterCollateral >= beforeCollateral (no loss) and increase is at most amount (can't magically create more than deposited)
        // Formulate both monotonicity and bounded increase.
        assert(
            // If deposit reverted, we allow any outcome. If it succeeded, then:
            reverted || (
                afterCollateral >= beforeCollateral
                && afterCollateral - beforeCollateral <= amount
            )
        );
    }

    receive() external payable {}
 }

