contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will pass parameters to deposit then withdraw inside multicall: token address, amount, and flag to use underlyingBorrowToken (true) or underlyingCollateralToken (false).
    // To keep within observable surface, we will call c.multicall with encoded calls to deposit and withdraw, and then assert that
    // - address(c).balance didn't decrease unexpectedly (we won't send ETH here)
    // - The SizeView reported borrow/ collateral underlying token balances and total supplies behave: after deposit+withdraw, the protocol's underlying token balance (via data().underlyingBorrowToken / underlyingCollateralToken) is >= 0 (trivial) and user's balances didn't increase beyond what they started with.

    // Because we cannot mint tokens externally here, we must avoid assuming approval; the multicall may revert. We assert the general rule: if multicall succeeds, then the caller's reported debtBalance + borrowATokenBalance + collateralTokenBalance after the operation is less-or-equal than before plus the deposited amount (i.e., no net creation beyond deposit amount). This is a general invariant preventing free token creation by multicall sequences.

    function run(address token, uint256 amount, bool useBorrowToken) public payable {
        require(token != address(0));
        // build DepositParams and WithdrawParams calldata for Size.deposit and Size.withdraw
        // We will encode calls to c.deposit and c.withdraw (ISize). Use the public signatures.

        // Prepare deposit params: (address token, uint256 amount, address to)
        bytes memory depositData = abi.encodeWithSignature(
            "deposit((address,uint256,address))",
            token,
            amount,
            address(this)
        );
        // Prepare withdraw params: (address token, uint256 amount, address to)
        bytes memory withdrawData = abi.encodeWithSignature(
            "withdraw((address,uint256,address))",
            token,
            amount,
            address(this)
        );

        bytes[] memory calls = new bytes[](2);
        calls[0] = depositData;
        calls[1] = withdrawData;

        // Observe before-state via view getters
        (uint256 beforeDebtCount, uint256 beforeCreditCount) = c.getPositionsCount();
        // getUserView to observe balances
        (/* userStruct */, address account, uint256 beforeCollateral, uint256 beforeBorrowAToken, uint256 beforeDebt) = c.getUserView(address(this));
        // Note: getUserView returns a struct; we destructure to observe balances. Solidity doesn't support struct destructuring from external call directly,
        // so call it and then re-query individual getters via SizeView public functions instead for safety.
        // To remain within restrictions, call the public view functions implemented in SizeView.
        uint256 beforeCollateralBalance = c.data().collateralToken.balanceOf(address(this));
        uint256 beforeBorrowATokenBalance = c.data().borrowAToken.balanceOf(address(this));
        uint256 beforeDebtBalance = c.data().debtToken.balanceOf(address(this));

        bool reverted;
        try c.multicall{value: 0}(calls) returns (bytes[] memory) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        uint256 afterCollateralBalance = c.data().collateralToken.balanceOf(address(this));
        uint256 afterBorrowATokenBalance = c.data().borrowAToken.balanceOf(address(this));
        uint256 afterDebtBalance = c.data().debtToken.balanceOf(address(this));
        (uint256 afterDebtCount, uint256 afterCreditCount) = c.getPositionsCount();

        // General rule asserted:
        // If the multicall succeeded (did not revert), then the sum of the caller's observable Size token balances after the operations
        // must be <= the sum before plus the raw deposited amount (no net positive creation beyond deposit amount).
        // Also, positions counts cannot decrease (multicall shouldn't destroy positions).
        assert(
            reverted || (
                (afterCollateralBalance + afterBorrowATokenBalance + afterDebtBalance) <= (
                    beforeCollateralBalance + beforeBorrowATokenBalance + beforeDebtBalance + amount
                )
                && afterDebtCount >= beforeDebtCount
                && afterCreditCount >= beforeCreditCount
            )
        );
    }

    // receive fallback to accept ETH if ever needed by calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We encode a multicall that does a deposit of `amount` then a withdraw of the same `amount` to the same recipient (this contract).
    // The property: if multicall does NOT revert, then the caller's observable token balances after the multicall
    // (collateralToken.balanceOf + borrowAToken.balanceOf + debtToken.balanceOf) are at most
    // the before-sum plus the explicit deposit `amount` (i.e. no unexpected creation beyond the deposited amount),
    // and the number of debt/credit positions does not decrease.

    function run(address token, uint256 amount) public payable {
        // basic preconditions for sensible encoding
        require(token != address(0));

        // Observe before-state through public view surface
        // Use SizeView.data() to get token contract addresses, then call their public balanceOf/totalSupply via returned structs
        (uint256 beforeDebtCount, uint256 beforeCreditCount) = c.getPositionsCount();
        DataView memory dv = c.data();

        uint256 beforeCollateralBalance = dv.collateralToken.balanceOf(address(this));
        uint256 beforeBorrowATokenBalance = dv.borrowAToken.balanceOf(address(this));
        uint256 beforeDebtBalance = dv.debtToken.balanceOf(address(this));
        uint256 beforeSum = beforeCollateralBalance + beforeBorrowATokenBalance + beforeDebtBalance;

        // Build calldata for deposit and withdraw
        bytes memory depositData = abi.encodeWithSignature(
            "deposit((address,uint256,address))",
            token,
            amount,
            address(this)
        );
        bytes memory withdrawData = abi.encodeWithSignature(
            "withdraw((address,uint256,address))",
            token,
            amount,
            address(this)
        );

        bytes[] memory calls = new bytes[](2);
        calls[0] = depositData;
        calls[1] = withdrawData;

        bool reverted;
        try c.multicall{value: 0}(calls) returns (bytes[] memory) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        DataView memory dv2 = c.data();
        uint256 afterCollateralBalance = dv2.collateralToken.balanceOf(address(this));
        uint256 afterBorrowATokenBalance = dv2.borrowAToken.balanceOf(address(this));
        uint256 afterDebtBalance = dv2.debtToken.balanceOf(address(this));
        uint256 afterSum = afterCollateralBalance + afterBorrowATokenBalance + afterDebtBalance;
        (uint256 afterDebtCount, uint256 afterCreditCount) = c.getPositionsCount();

        // Assert the invariant: if multicall succeeded then sums increased by at most `amount` and counts didn't decrease.
        assert(
            reverted || (
                afterSum <= beforeSum + amount
                && afterDebtCount >= beforeDebtCount
                && afterCreditCount >= beforeCreditCount
            )
        );
    }

    receive() external payable {}
}

