        uint256 beforeSum = beforeCollateralBalance + beforeBorrowATokenBalance + beforeDebtBalance;

        // Build calldata for deposit and withdraw as plain bytes arrays
        bytes[] memory calls = new bytes[](2);
        // Note: encodeWithSelector uses the public selector of c
        calls[0] = abi.encodeWithSelector(c.deposit.selector, DepositParams({token: token, amount: amount, to: address(this)}));
        calls[1] = abi.encodeWithSelector(c.withdraw.selector, WithdrawParams({token: token, amount: amount, to: address(this)}));

        bool reverted;
        // Top-level state-changing call on c (must be flat statement)
        try c.multicall{value: 0}(calls) returns (bytes[] memory) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        DataView memory dvAfter = c.data();
        uint256 afterCollateralBalance = dvAfter.collateralToken.balanceOf(address(this));
        uint256 afterBorrowATokenBalance = dvAfter.borrowAToken.balanceOf(address(this));
        uint256 afterDebtBalance = dvAfter.debtToken.balanceOf(address(this));
        uint256 afterSum = afterCollateralBalance + afterBorrowATokenBalance + afterDebtBalance;
        (uint256 afterDebtCount, uint256 afterCreditCount) = c.getPositionsCount();

        // Assert the general rule: if multicall succeeded then
        // - the aggregate observable balances did not increase,
        // - and the counts of positions did not decrease.
        assert(
            reverted || (
                afterSum <= beforeSum
                && afterDebtCount >= beforeDebtCount
                && afterCreditCount >= beforeCreditCount
            )
        );
    }

    // Accept ETH if protocol needs to send back
    receive() external payable {}
}

