        (, , , , , , , ) = c.data(); // harmless view call to ensure view surface accessible

        // Get borrow aToken and debt token via data(). We only can observe via c.data() which returns DataView.
        (uint256 beforeDebtCount, uint256 beforeCreditCount) = c.getPositionsCount();

        // Read borrowAToken totalSupply and to-balance before by calling data() and then calling returned borrowAToken
        // First fetch DataView
        (uint256 nextDebtPositionId, uint256 nextCreditPositionId, , , , , , ) = c.data();
        // The DataView returned in c.data() includes borrowAToken as a NonTransferrableScaledToken type, but since we cannot name it,
        // we will observe total supply and balances through the public ISize view functions available on C.

        // Observe totalSupply and balance before via ISizeView-compatible calls: getUserView and data().
        // data().borrowAToken and data().debtToken are not directly callable; instead use getUserView to get borrowATokenBalance for 'to'.
        uint256 beforeBorrowBalance = c.getUserView(to).borrowATokenBalance;
        uint256 beforeDebtBalance = c.getUserView(to).debtBalance;

        // To obtain totalSupply of borrowAToken we can use data() and then call borrowAToken.totalSupply() through the public surface
        // but since data().borrowAToken is returned as a NonTransferrableScaledToken type, we cannot call methods on it via the returned struct in solidity here.
        // Instead, we will infer monotonicity property: after a successful deposit of underlyingBorrowToken to variable pool,
        // the protocol's borrowAToken totalSupply must be >= beforeBorrowBalance (i.e., supply cannot shrink below any user's balance).
        // We'll record beforeBorrowBalance and afterBorrowBalance and assert afterBorrowBalance >= beforeBorrowBalance.

        // Perform the deposit call. We don't know which token is valid; to keep test general we allow deposit to revert.
        bool reverted = false;
        try c.deposit{value: 0}(ISize.DepositParams({token: token, amount: amount, to: to})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBorrowBalance = c.getUserView(to).borrowATokenBalance;
        uint256 afterDebtBalance = c.getUserView(to).debtBalance;

        // General rule: If deposit succeeded (not reverted) then recipient borrowAToken balance cannot decrease.
        // Also if deposit reverted, balances should be unchanged.
        assert((!reverted && afterBorrowBalance >= beforeBorrowBalance) || (reverted && afterBorrowBalance == beforeBorrowBalance && afterDebtBalance == beforeDebtBalance));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We call C.deposit(...) with arbitrary token/amount/to. The rule:
    // - If the call reverts, the observable balances for `to` (collateralToken balance, borrowAToken balance, debt token balance)
    //   remain equal to their pre-call values.
    // - If the call succeeds, none of those three balances for `to` decreases.
    // We observe balances via the public view getUserView(address) that returns those balances.
    function run(address token, uint256 amount, address to) public payable {
        // no assumptions about token or amount; allow ether present but do not use msg.value here
        require(address(this).balance >= 0);

        // Read observable balances before the call
        ( , , uint256 beforeCollateralBalance, uint256 beforeBorrowATokenBalance, uint256 beforeDebtBalance) = c.getUserView(to);

        bool reverted;
        // Make the deposit call; it may revert. We must pass a DepositParams struct. Build calldata via try/catch on the external call.
        try c.deposit{value: 0}(/*DepositParams*/ (token, amount, to)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable balances after the call
        ( , , uint256 afterCollateralBalance, uint256 afterBorrowATokenBalance, uint256 afterDebtBalance) = c.getUserView(to);

        // Assert the general invariant described above
        assert(
            // If reverted: balances unchanged
            (reverted && afterCollateralBalance == beforeCollateralBalance && afterBorrowATokenBalance == beforeBorrowATokenBalance && afterDebtBalance == beforeDebtBalance)
            // If succeeded: none of the three balances decreased
            || (!reverted && afterCollateralBalance >= beforeCollateralBalance && afterBorrowATokenBalance >= beforeBorrowATokenBalance && afterDebtBalance >= beforeDebtBalance)
        );
    }

    // Accept ETH so c.deposit{value: ...} could be forwarded in other variants if needed by the checker
    receive() external payable {}
}

