contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We deposit then immediately withdraw; ensure positions counters didn't increase and withdraw returns <= deposited
    function run(address token, uint256 amount, address to) public payable {
        // ensure sensible params
        require(token != address(0) && to != address(0) && amount > 0);
        // transfer Ether to this contract if depositing WETH is intended must be done off-chain by funding this contract
        // record positions counters before
        (uint256 beforeDebtCount, uint256 beforeCreditCount) = c.getPositionsCount();

        // prepare deposit params struct ABI-encoded call
        // calls must be top-level; use c.deposit
        // build DepositParams in calldata by matching struct: (address token, uint256 amount, address to)
        // call deposit (payable) — if token is WETH and caller wants to send ETH, require balance
        if (token == address(c.oracle().priceFeed)) {
            // unlikely mapping; just proceed with non-payable path
        }

        // If depositing native ETH: user would send msg.value. We don't support that here; call without value.
        // perform deposit
        bytes memory depositCalldata = abi.encodeWithSelector(
            c.deposit.selector,
            // DepositParams
            token,
            amount,
            to
        );
        // perform low-level call to forward any msg.value if present
        (bool okDeposit, ) = address(c).call{value: 0}(depositCalldata);
        // deposit may revert due to many protocol constraints; we capture revert flag
        bool depositReverted = !okDeposit;

        // perform withdraw attempt of same amount to same recipient
        bytes memory withdrawCalldata = abi.encodeWithSelector(
            c.withdraw.selector,
            // WithdrawParams
            token,
            amount,
            to
        );
        (bool okWithdraw, ) = address(c).call{value: 0}(withdrawCalldata);
        bool withdrawReverted = !okWithdraw;

        // read positions after
        (uint256 afterDebtCount, uint256 afterCreditCount) = c.getPositionsCount();

        // General rule asserted:
        // If both deposit and withdraw succeeded (did not revert), then the positions counters must be unchanged
        // and the withdraw event should have withdrawn at most the deposited amount. We cannot read events here,
        // but we can observe that if withdraw succeeded then the contract's borrowAToken/collateral balances decreased
        // in public view are not directly accessible; instead we assert counters unchanged and that after counts >= before counts
        // (i.e., no new positions were created). To make a non-trivial relation, assert: if both calls succeeded then counts equal and after==before.
        assert((depositReverted || withdrawReverted) || (afterDebtCount == beforeDebtCount && afterCreditCount == beforeCreditCount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: maxDueDate, arrays for tenors, aprs, multipliers
    function run(uint256 maxDueDate, uint256[] calldata tenors, int256[] calldata aprs, uint256[] calldata marketRateMultipliers) public payable {
        // basic ABI-validity preconditions for the yield curve lengths to match what execute expects
        require(tenors.length == aprs.length && tenors.length == marketRateMultipliers.length);
        // Build BuyCreditLimitParams and call buyCreditLimit as top-level state-changing call
        BuyCreditLimitParams memory params = BuyCreditLimitParams({maxDueDate: maxDueDate, curveRelativeTime: YieldCurve({tenors: tenors, aprs: aprs, marketRateMultipliers: marketRateMultipliers})});

        bool reverted = false;
        try c.buyCreditLimit(params) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read back the stored loan offer for msg.sender (which is this contract) via the public view getUserView
        // getUserView is view and returns a struct; it's allowed to call
        ISize.UserView memory v = c.getUserView(address(this));

        // If the call did not revert, then the stored loanOffer must reflect the input: maxDueDate equal and tenors length equal
        assert(reverted || (v.user.loanOffer.maxDueDate == maxDueDate && v.user.loanOffer.curveRelativeTime.tenors.length == tenors.length));
    }

    // needed to receive ETH in case caller funds this test contract off-chain
    receive() external payable {}
}

